import Vue from 'vue';
import { Component, Prop } from 'vue-property-decorator';
import { OPTIONS } from '../../options';

@Component({
    name: 'LoadingSplash'
})
export default class LoadingSplash extends Vue {
    @Prop({
        required: true,
        type: Boolean
    })
    public visible: boolean;

    @Prop({
        required: true,
        type: Number
    })
    public progress: number;

    public options = OPTIONS;

    public getBackgroundColour(): string {
        return this.options.splashBackgroundColour ?? this.options.theme.midAccent.string;
    }
}
